// AI Usage Note
// Generated by Claude (Claude Code): this coverage configuration for monocart-coverage-reports.
// How it was verified: unit and combined test runs report exactly the files of the measured categories,
// untested files appear with 0%, and the HTML report is a single file.
// Reviewed by: viktoriyabaran
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Categories left out of coverage: docs/architecture/mechanisms/testing.md, rule 3.
const excluded = [
  // Generated code
  /\/infra\/prisma\/generated\//,
  // Types
  /\/types\//,
  /\/core\/common\/page\.(ts|js)$/,
  // Ports
  /\/core\/[^/]+\/(repositories|adapters)\//,
  // Temporary stand-ins
  /\/infra\/stubs\//,
  /\/infra\/messaging\/console-messaging-provider\.(ts|js)$/,
  // Wiring and start-up
  /\.module\.(ts|js)$/,
  /\/(api|import)\/main\.(ts|js)$/,
  /\/api\/common\/config\.(ts|js)$/,
  // Declarations
  /\/schemas\//,
  /\/api\/common\/(routes|tags|registry|api-exception)\.(ts|js)$/,
  /\/core\/common\/domain-error\.(ts|js)$/,
  // Tooling
  /\/api\/common\/openapi\.(ts|js)$/,
  /\/scripts\//,
];

export default {
  name: 'Nearby test coverage',
  reports: [['v8', { inline: true }], 'console-summary'],
  entryFilter: (entry) => entry.url.includes('/dist/') && !entry.url.includes('/node_modules/'),
  // Called with dist/ paths for untested files first, then with the src/ paths from the source maps.
  sourceFilter: (sourcePath) =>
    /^(dist|src)\//.test(sourcePath) && !excluded.some((pattern) => pattern.test(sourcePath)),
  all: {
    dir: ['./dist'],
    filter: { '**/*.js': true, '**/*': false },
    // tsc source maps do not embed the TypeScript sources, which the report needs for files no test loads.
    transformer: async (entry) => {
      const file = fileURLToPath(entry.url);
      const map = JSON.parse(await readFile(`${file}.map`, 'utf8'));
      map.sourcesContent = await Promise.all(
        map.sources.map((source) => readFile(path.resolve(path.dirname(file), map.sourceRoot ?? '', source), 'utf8')),
      );
      entry.sourceMap = map;
    },
  },
};
